        db $F7,$FF,$FF
; [Init] CPU reset entry point. Switches to native mode, disables interrupts, sets up stack, jumps to main init.
ResetHandler:
        CLC
        XCE
        SEI
        SEP #$20
        REP #$10
        LDA.B #$80
        STA.W $2100
        LDA.B #$01
        STA.W $420D
        STZ.W $420C
        STZ.W $00C0
        LDX.W #$1FFF
        TXS
        JML.L InitGame
; [Interrupt] V-blank interrupt handler (60Hz). Jumps to GameModeDispatcher at $808000 for game state processing during V-blank
NMI_Handler:
        JML.L GameModeDispatcher
; [Interrupt] Hardware IRQ handler (H/V timer interrupts). Jumps to IRQ_Dispatcher at $808004 for scanline-based effects
IRQ_Handler:
        JML.L IRQ_Dispatcher
        db $5C,$95,$9D,$80
; [Init] Main game initialization: sets data bank, switches to 8-bit mode, calls hardware init and save data verification
InitGame:
        PHK
        PLB
        SEP #$20
        JSL.L CheckInterlaceAndInit
        JSL.L CheckSaveData
        JSR.W ResetGameState
        JSL.L InitDisplaySystem
        JSL.L UploadSoundData
        JSL.L UpdateCollision
        JSL.L ProcessAI
        REP #$20
        LDA.W #$0495
        STA.B $B4
        LDA.W #$00C9
        STA.B $B6
        LDA.W #$0000
        STA.B $B8
        LDA.W #$007F
        STA.B $BA
        LDA.L $C90493
        STA.B $BC
        JSL.L DecompressData
        JSL.L InitAudioController
; [MainLoop] Main game loop: calls graphics update, checks $00F4 frame delay counter, processes game frame or updates timers based on delay
MainGameLoop:
        JSL.L UpdateGraphics
        REP #$20
        LDA.W $00F4
        BEQ ProcessGameFrame
        DEC.W $00F4
        LDA.W $00F4
        LSR A
        BCC UpdateTimers
; [MainLoop] Processes one game frame: calls $AA7E (game logic), checks $13F1 pause flag, updates game state or timers
ProcessGameFrame:
        SEP #$20
        JSR.W GameLogicProcessor
        LDA.W $13F1
        BEQ UpdateGameState
        db $80,$3D
; [GameState] Updates game state: calls $D76C, $8B81, $A97F, sets $12E6=1 if zero, checks $12E8 and $12EB for event handling
UpdateGameState:
        JSR.W UpdateAudioSystem
        JSR.W ProcessAudioCommands
        JSR.W CheckGameStateFlags
        LDA.W $12E6
        BNE UpdateTimers
        LDA.B #$01
        STA.W $12E6
        LDA.W $12E8
        BNE CheckInputEvents
        LDA.W $12EB
        BNE HandleGameEvents
        LDA.W $164B
        BNE HandleGameEvents
        LDA.W $18E4
        BNE HandleGameEvents
        REP #$20
        INC.W $0F26
        SEP #$20
; [GameState] Handles game events: calls $8BDB, checks $12E8, calls $8C0C if non-zero, otherwise calls $8C12
HandleGameEvents:
        LDA.B #$00
        XBA
        LDA.W $00C8
        TAX
        JSR.W ($80F5,X)
; [Input] Checks input events: calls $8C18, checks $12E6, calls $8C1E if non-zero
CheckInputEvents:
        SEP #$20
        STZ.W $12E6
; [Timer] Updates game timers: checks $1274, calls $80D52C if positive, otherwise proceeds to render frame
UpdateTimers:
        SEP #$20
        LDA.W $1274
        BMI RenderFrame
        JSL.L AudioProcessingRoutine
; [MainLoop] Main rendering routine. Checks $124C render flag, sends $12C2 to APU port $2140 if $12C3 set, waits for V-blank, calls graphics routines
RenderFrame:
        LDA.W $124C
        BEQ CheckInputEvents
        STZ.W $124C
        LDA.W $12C3
        BEQ SyncWithVBlank
        LDA.W $12C2
        STA.W $2140
; [Helper] Waits for V-blank by checking $164B. If non-zero, calls $81E0B2 (graphics update), otherwise jumps to VRAM clear
SyncWithVBlank:
        LDX.W $164B
        BEQ ClearVRAM
        JSL.L SetupHDMAChannel4
; [VRAM] Jumps to $806E to clear VRAM and initialize display hardware registers
ClearVRAM:
        JMP.W MainGameLoop
        db $20,$81,$38,$81,$BB,$81,$C1,$82
        db $1C,$83
        db $1D,$83,$17,$84,$1E,$84,$67,$84,$26,$83,$2B,$83,$3A,$83,$30,$83
        db $35,$83
        db $B6,$81
        db $44,$84,$2B,$84,$C1,$82,$1B,$81
; [Input] Calls ProcessInputCombination and returns. Entry: 8-bit A, 16-bit X/Y.
ProcessInputAndReturn:
        JSL.L ProcessInputCombination
        RTS
; [Init] Checks $00D5, calls InitHardware if zero, sets $00C8=2, $00C9=0
CheckD5AndInit:
        PHP
        REP #$30
        SEP #$20
        LDA.W $00D5
        BNE RestoreFlagsAndReturnSimple
        JSL.L InitHardware
        LDA.B #$02
        STA.W $00C8
        STZ.W $00C9
; [Helper] Restores processor flags and returns from subroutine (PLP/RTS). Entry: 8-bit A, 16-bit X/Y.
RestoreFlagsAndReturnSimple:
        PLP
        RTS
; [Menu] Calls ProcessMenuState routine and returns
CallMenuProcessor:
        JSL.L ProcessMenuState
        RTS
; [GameState] Checks special game condition at $1274, sets flags based on comparison with $12C0
CheckSpecialCondition:
        PHP
        SEP #$20
        REP #$10
        LDA.W $18F3
        BEQ DispatchGameEvent
        REP #$20
        LDA.W $1C56
        BPL DispatchGameEvent
        SEP #$20
        STZ.W $18F3
        LDA.B #$01
        STA.W $00D4
        STA.W $05A0
        STA.W $05A1
        STA.W $05A2
; [GameState] Dispatches to game event handler based on $05A1 value using jump table at $80817B
DispatchGameEvent:
        SEP #$20
        LDA.W $05A2
        BEQ ReturnAfterEventCheck
        LDX.W #$0000
        STX.W $0320
        LDA.B #$00
        XBA
        LDA.W $05A1
        ASL A
        TAX
        JMP.W ($817B,X)
; [Helper] Simple return after checking game event conditions (PLP/RTS). Entry: 8-bit A, 16-bit X/Y.
ReturnAfterEventCheck:
        PLP
        RTS
; [StateMachine] Jump table for game event handlers (2-byte addresses)
GameEventJumpTable:
        db $93,$81
        db $7F,$81
        DEC.W $00E4
        DEC.W $00E5
        LDA.W $00E4
        CMP.B #$17
        BNE ReturnFromInterrupt
        STZ.W $05A2
; [Helper] Simple return from interrupt handler.
ReturnFromInterrupt:
        PLP
        RTS
        db $28,$60,$EE,$E4,$00,$EE,$E5,$00,$AD,$E4,$00,$C9,$46,$D0,$03,$9C
        db $A2,$05,$28,$60
; [Music] Initializes audio system: sets $12C2=$12C3=$12C4=0, $12C5=2, calls $80D52C for audio setup
SetDefaultAudioState:
        PHP
        SEP #$20
        JSL.L InitAudioController
        LDA.B #$1A
        STA.W $00CA
        STZ.W $00CB
        PLP
        RTS
        db $22,$C0,$FD,$82,$60
; [Music] Checks audio conditions and updates audio system state
checkAudioAndUpdate:
        PHP
        SEP #$20
        REP #$10
        LDA.W $00FC
        BNE CheckAudioConditions
        db $AD,$CC,$00,$0D,$D9,$06,$0D,$D9,$07,$D0,$16,$80,$11
; [Music] Checks conditions for audio playback and state.
CheckAudioConditions:
        LDA.W $00CC
        ORA.W $06D9
        ORA.W $07D9
        ORA.W $06B0
        ORA.W $07B0
        BNE UpdateAudioState
        JSR.W SetDefaultAudioState
; [Music] Updates audio system state based on conditions.
UpdateAudioState:
        LDA.W $18ED
        BEQ UpdateTimerValues
        DEC.W $18ED
; [Timer] Updates timer values and checks for timeouts.
UpdateTimerValues:
        JSR.W CheckSpecialCondition
        LDA.W $00C9
        BNE ProcessTimedEvents
        JSR.W UpdateAudioDSP
; [Timer] Processes events triggered by timers.
ProcessTimedEvents:
        LDA.W $12E2
        BEQ UpdateCounter
        db $22,$00,$80,$82,$4C,$9B,$82
; [Timer] Updates counter value and checks thresholds.
UpdateCounter:
        REP #$20
        STZ.W $12E4
        SEP #$20
        LDA.W $12EB
        BEQ CheckCounterState
        JSL.L DispatchGameSubroutine
        JMP.W UpdateFrameCounter
; [Timer] Checks counter state and branches based on value.
CheckCounterState:
        LDA.W $18E4
        BEQ ResetCounter
        JSL.L LoadScriptData
        BRA UpdateFrameCounter
; [Timer] Resets counter to initial value.
ResetCounter:
        LDA.W $1498
        BEQ CheckTransferCondition
        JSL.L InitAudioControllerWrapper
; [Memory] Checks if memory transfer should occur based on $164B flag. Calls transfer routine if set.
CheckTransferCondition:
        LDA.W $164B
        BEQ CheckGameFlags
        JSL.L TransferMemoryBlock
        BRA UpdateFrameCounter
; [GameState] Checks multiple game flags ($00FA, $00D4, $00D5, $05F0, $05F1). Calls event handler if any flag is set.
CheckGameFlags:
        LDA.W $00FA
        ORA.W $00D4
        ORA.W $00D5
        ORA.W $05F0
        ORA.W $05F1
        BEQ ProcessPeriodicEvent
        JSR.W ClearStatusFlags
; [Timer] Processes periodic events based on frame counter.
ProcessPeriodicEvent:
        JSL.L ClearVRAMArea
        JSL.L UpdatePlayer
        JSL.L ProcessLevelLogic
        JSL.L UpdateEnemies
        JSL.L processEntityCleanup
        JSL.L ProcessMultiLevelGraphics
        JSL.L UpdateCamera
        JSL.L ProcessObjects
        JSL.L UpdateAnimations
        JSL.L ProcessEffects
        JSL.L UpdateHUD
        JSL.L ProcessUI
        JSR.W SimpleReturnRoutine
        JSL.L CheckObjectProcessing
        JSL.L ProcessGameEntities
        JSL.L initEntityBuffers
        JSL.L HandleEventState1CA9
        LDA.W $0F26
        AND.B #$03
        CMP.B #$02
        BNE UpdateFrameCounter
        JSL.L HandleSpecialEvents
; [Timer] Updates frame counter and related timing variables.
UpdateFrameCounter:
        REP #$20
        STZ.W $12E2
        STZ.W $12E4
        PLP
        RTS
        db $08,$E2,$20,$AD,$60,$05,$89,$40,$F0,$10,$AD,$6D,$05,$89,$20,$F0
        db $09,$9C,$00,$08,$9C,$00,$09,$9C,$00,$0A,$28,$60
; [MainLoop] Main game frame logic processor. Checks conditions, calls game subsystems or clears VRAM. Entry: 8-bit A, 16-bit X/Y.
ProcessGameFrameLogic:
        PHP
        JSR.W CheckSpecialCondition
        LDA.W $00C9
        BNE CheckGameUpdateCondition
        JSL.L processPlayerInput
; [GameState] Checks $164B and $00C8 to determine if game update should run or VRAM should be cleared
CheckGameUpdateCondition:
        LDA.W $164B
        BEQ CheckGameMode22_Branch
        JSL.L TransferMemoryBlock
        BRA ReturnFromGameUpdate
; [GameState] Checks if game mode is $22, branches to UpdateGameSubsystems or calls ClearVRAMArea. Branch target from $8082CE.
CheckGameMode22_Branch:
        LDA.W $00C8
        CMP.B #$22
        BEQ UpdateGameSubsystems
        JSL.L ClearVRAMArea
; [MainLoop] Updates all game subsystems: physics, AI, rendering, etc.
UpdateGameSubsystems:
        JSL.L processGameMode
        JSL.L UpdatePlayer
        JSL.L UpdateEnemies
        JSL.L ProcessLevelLogic
        JSL.L UpdateCamera
        JSL.L ProcessObjects
        JSL.L UpdateAnimations
        JSL.L ProcessEffects
        JSL.L UpdateHUD
        JSL.L ProcessUI
        LDA.W $0F26
        AND.B #$03
        CMP.B #$02
        BNE ReturnFromGameUpdate
        JSL.L HandleSpecialEvents
; [Helper] Clean return from game update functions.
ReturnFromGameUpdate:
        PLP
        RTS
        db $60,$60
; [Music] Processes audio frame and UI updates
processAudioAndUI:
        JSL.L ProcessAudioFrame
        JSL.L ProcessUI
        RTS
; [LevelLoad] Wrapper that calls InitLevelState JSL and returns
InitLevelStateWrapper:
        JSL.L InitLevelState
        RTS
; [Helper] Calls external routine at $9FEDB9 and returns
CallExternalRoutineB9:
        JSL.L checkGameStateAndMemory
        RTS
; [Helper] Calls external routine at $9FF54D and returns
callExternalRoutine1:
        JSL.L processSystemBeep
        RTS
        JSL.L checkGameStateAndMemory
        RTS
; [MainLoop] Main game loop function. Processes timers, audio, game state, and calls various subsystems. Entry: 8-bit A, 16-bit X/Y.
mainGameLoop:
        PHP
        SEP #$20
        REP #$10
        LDA.W $18ED
        BEQ CODE_408347
        db $CE,$ED,$18
CODE_408347:
        JSR.W CheckSpecialCondition
        LDA.W $0561
        BIT.B #$80
        BEQ CODE_40836C
        LDA.W $056D
        BIT.B #$20
        BEQ CODE_40836C
