        db $00,$9C,$CB,$00
CODE_40836C:
        LDA.W $00C9
        BNE CODE_40837C
        JSR.W UpdateAudioDSP
        LDA.B #$01
        STA.W $1CA9
        STZ.W $00FA
CODE_40837C:
        LDA.W $12E2
        BEQ CODE_408388
        db $22,$00,$80,$82,$4C,$0D,$84
CODE_408388:
        REP #$20
        STZ.W $12E4
        SEP #$20
        LDA.W $12EB
        BEQ CODE_40839A
        db $22,$3B,$DB,$82,$80,$73
CODE_40839A:
