        JSL.L initEntityBuffers
        JSL.L HandleEventState1CA9
        LDA.W $0F26
        AND.B #$03
        CMP.B #$02
        BNE CODE_40840D
        JSL.L HandleSpecialEvents
CODE_40840D:
        REP #$20
        STZ.W $12E2
        STZ.W $12E4
        PLP
        RTS
