; [GameState] Checks $0895 and transitions to game mode 4. If $0895 negative, sets $1CA6=2 first. Entry: 8-bit A, 16-bit X/Y.
CheckGameModeTransition:
        PHP
        SEP #$20
        REP #$10
        LDA.W $0895
        BMI SetGameMode4
        LDA.W #$8D02
