SetGameMode4:
        LDA.B #$04
        STA.W $00C8
        STZ.W $00C9
        PLP
        RTS
; [GameState] Checks $1CBE for game reset condition. If set, prepares memory reset and calls ClearMemoryBlock. Otherwise resets game mode to 4. Entry: 8-bit A, 16-bit X/Y.
