CheckSaveData:
        PHB
        PHP
        PHK
        PLB
        SEI
        REP #$30
        LDX.W #$0000
; [Save] Verifies first save block: compares 16 bytes from $8B13 with $0550, jumps to InitializeRAM on mismatch
VerifySaveData:
        LDA.W $8B13,X
        CMP.W $0550,X
        BNE InitializeRAM
        INX
        INX
        CPX.W #$0010
        BNE VerifySaveData
