        db $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
; [VRAM] Uploads 256 bytes from WRAM $7E:2000 to VRAM. VRAM destination depends on $00C8 and $0F26 values.
UploadVRAMData:
        PHP
        SEP #$20
        REP #$10
        LDA.W $00C8
        CMP.B #$0A
        BEQ ReturnFromVRAMUpload
        CMP.B #$14
        BEQ ReturnFromVRAMUpload
        LDA.W $0F26
        AND.B #$03
        BNE CheckVRAMDest2
        LDX.W #$5860
        BRA UploadVRAMBuffer
; [VRAM] Checks if $0F26 & 3 == 2, sets VRAM dest to $5AC0
CheckVRAMDest2:
        CMP.B #$02
        BNE ReturnFromVRAMUpload
        LDX.W #$5AC0
; [VRAM] Uploads VRAM buffer to PPU: sets VRAM address from X, DMA from $7E2000 to $2118, 256 bytes
UploadVRAMBuffer:
        STX.W $2116
        LDA.B #$01
        STA.W $4300
        LDA.B #$80
        STA.W $2115
        LDA.B #$18
        STA.W $4301
        LDX.W #$2000
        STX.W $4302
        LDA.B #$7E
        STA.W $4304
        LDX.W #$0100
        STX.W $4305
        LDA.B #$01
        STA.W $420B
; [Helper] Clean return from VRAM upload function
ReturnFromVRAMUpload:
        PLP
        RTS
; [GameState] Dispatches to game mode handler based on $00C8 value via jump table at $9CBC
GameModeDispatcher:
        PHD
        PHP
        PHB
        PHK
        PLB
        REP #$30
        PHY
        PHX
        PHA
        LDA.W #$0000
        TCD
        SEP #$20
        LDA.W $4210
        LDA.W $0080
        ORA.B #$80
        STA.W $2100
        SEP #$20
        LDA.B #$00
        XBA
        LDA.W $00C8
        TAX
        JMP.W ($9CBC,X)
        db $FC,$9C,$E8,$9C,$56,$9D,$56,$9D
        db $FC,$9C
        db $FC,$9C,$FC,$9C,$FC,$9C
        db $56,$9D
        db $56,$9D,$56,$9D,$56,$9D,$FC,$9C,$FC,$9C
        db $FC,$9C
        db $56,$9D
        db $56,$9D
        db $FC,$9C,$FC,$9C,$50
        db $00
        db $00
        db $00
        db $B0
        db $00
        LDA.B #$00
        XBA
        LDA.W $1E5F
        ASL A
        TAX
        LDA.W $9CE2,X
        STA.W $1E68
        LDA.W $1E66
        STA.W $1E6A
        LDA.W $1655
        BNE IRQ_ReturnPath1
        JSR.W UpdateMode7Registers
        LDA.W $0F22
        BEQ IRQ_Handler_Main
        JSR.W UpdateColorMathRegisters
; [Interrupt] Main IRQ handler with two return paths. Sets up HDMA, enables NMI, calls sound routines.
IRQ_Handler_Main:
        JSR.W UpdatePPURegisters
        JSR.W UpdateScrollRegisters
        JSR.W UploadCGRAM
        LDA.W $00C0
        STA.W $420C
        LDA.B #$81
        STA.W $4200
        LDA.W $0080
        STA.W $2100
        LDA.B #$01
        STA.W $124C
        JSR.W ReadControllerAuto
        JSR.W ReadControllerManual
; [Helper] IRQ return path 1: restores all registers and returns from interrupt
IRQ_ReturnPath1:
        REP #$30
        PLA
        PLX
        PLY
        PLB
        PLP
        PLD
        RTI
; [Helper] IRQ return path 2: calls $F2C0 and $EBF7, sets $4200=$31, restores registers
IRQ_ReturnPath2:
        SEP #$20
        JSR.W ReadControllerAuto
        JSR.W ReadControllerManual
        LDA.B #$31
        STA.W $4200
        LDA.W $00C0
        STA.W $420C
        REP #$30
        PLA
        PLX
        PLY
        PLB
        PLP
        PLD
        RTI
        LDA.W $1655
        BNE IRQ_ReturnPath3
        JSR.W SetupVRAMDMA
        LDA.W $12E6
        BNE IRQ_ReturnPath2
        JSR.W UpdateMode7Registers
        LDA.W $0F22
        BEQ IRQ_HandlerEntry2
        JSR.W UpdateColorMathRegisters
; [Interrupt] Alternate IRQ handler entry point
IRQ_HandlerEntry2:
        JSR.W UpdateScrollRegisters
        JSR.W UpdatePPURegisters
        SEP #$20
        JSR.W ReadControllerAuto
        JSR.W ReadControllerManual
        LDA.B #$31
        STA.W $4200
        LDA.B #$01
        STA.W $124C
; [Helper] IRQ return path 3: sets HDMA enable from $00C0, restores registers
IRQ_ReturnPath3:
        LDA.W $00C0
        STA.W $420C
        REP #$30
        PLA
        PLX
        PLY
        PLB
        PLP
        PLD
        RTI
        db $4C,$95,$9D
; [Interrupt] IRQ handler that dispatches to different handlers based on $124D. Sets up H-timer.
IRQ_Dispatcher:
        PHP
        REP #$30
        PHB
        PHA
        PHX
        PHY
        PHD
        PHK
        PLB
        LDA.W #$0000
        TCD
        SEP #$30
        LDA.W $4211
        LDA.B #$01
        STA.W $4200
        LDX.W $124D
        JSR.W ($9DCC,X)
        SEP #$20
        LDA.B #$80
        STA.W $4207
        STZ.W $4208
        STZ.W $420A
        REP #$30
        PLD
        PLY
        PLX
        PLA
        PLB
        PLP
        RTI
        db $DE,$9D,$10,$9E,$42,$9E,$7C,$9E
        db $D6,$9D,$E2,$20,$A9,$0F,$8D,$2C,$21,$60
; [Init] Initializes PPU for mode 1: sets screen brightness, BG mode, scroll registers, V-timer, enables display
InitPPUForMode1:
        LDA.W $0080
        STA.W $2100
        LDA.W $0082
        STA.W $2105
        STZ.W $2111
        STZ.W $2111
        STZ.W $2112
        STZ.W $2112
        LDA.W $00E4
        CLC
        ADC.B #$19
        STA.W $4209
        LDA.W $00A0
        STA.W $212C
        LDA.B #$02
        STA.W $124D
        LDA.B #$31
        STA.W $4200
        RTS
; [Scrolling] Updates PPU scroll registers: sets BG mode, V-timer, horizontal/vertical scroll from $052D-$0531
UpdatePPUScroll:
        LDA.W $0082
        STA.W $2105
        LDA.B #$D1
        SEC
        SBC.W $00E5
        STA.W $4209
        LDA.W $052D
        STA.W $2111
        LDA.W $052E
        STA.W $2111
        LDA.W $0530
        STA.W $2112
        LDA.W $0531
        STA.W $2112
        LDA.B #$04
        STA.W $124D
        LDA.B #$31
        STA.W $4200
        RTS
; [Interrupt] IRQ subroutine 2: handles screen brightness based on $00E5, sets up next IRQ timing
IRQ_Subroutine2:
        LDA.W $00E5
        CMP.B #$01
        BNE IRQ_Subroutine1
        LDA.W $0080
        ORA.B #$80
        STA.W $2100
        BRA SetupNextIRQ
; [Interrupt] IRQ subroutine 1: handles screen brightness and layer enables
IRQ_Subroutine1:
        LDA.W $05A0
        BEQ SetupNextIRQ
        LDA.W $05F0
        BNE SetLayerEnables
        LDA.B #$0F
        STA.W $2100
; [Effects] Sets main screen (BG1+BG2) and sub screen (none) layer enables
SetLayerEnables:
        LDA.B #$04
        STA.W $212C
        LDA.B #$00
        STA.W $212D
; [Interrupt] Sets up next IRQ timing: V-counter=$D1, IRQ mode=6, enables IRQ
SetupNextIRQ:
        LDA.B #$D1
        STA.W $4209
        LDA.B #$06
        STA.W $124D
        LDA.B #$31
        STA.W $4200
        RTS
; [Interrupt] IRQ subroutine 3: restores screen brightness, clears HDMA, sets up next IRQ from $00E4
IRQ_Subroutine3:
        LDA.W $0080
        ORA.B #$80
        STA.W $2100
        STZ.W $124D
        STZ.W $420C
        STZ.W $420C
        LDA.W $00A0
        STA.W $212C
        LDA.W $00A1
        STA.W $212D
        LDA.W $12E6
        BNE IRQ_Subroutine4
        JSR.W UploadCGRAM
        JSR.W UploadVRAMData
; [Interrupt] IRQ subroutine 4: sets up next IRQ timing from $00E4, enables IRQ
IRQ_Subroutine4:
        LDA.W $00E4
        STA.W $4209
        LDA.B #$B1
        STA.W $4200
        RTS
; [Init] Updates PPU registers from RAM values $0081-$0093 (BGMODE, MOSAIC, BGSC, BGNBA, M7 params)
UpdatePPURegisters:
        PHP
        SEP #$20
