        LDA.W $0091
        STA.W $211E
        LDA.W $0092
        STA.W $211E
        LDA.W $0093
        STA.W $211F
        LDA.W $0094
        STA.W $211F
        LDA.W $0095
        STA.W $2120
        LDA.W $0096
        STA.W $2120
        LDA.W $0097
        STA.W $2123
        LDA.W $0098
