; [Palette] Uploads 512 bytes ($0200) from ROM $00:0320 to CGRAM starting at palette entry 0
UploadCGRAM:
        PHP
        SEP #$20
        REP #$10
        LDA.B #$00
        STA.W $2121
        LDA.B #$02
        STA.W $4300
        LDA.B #$22
        STA.W $4301
        LDX.W #$0320
        STX.W $4302
        LDA.B #$00
        STA.W $4304
        LDX.W #$0200
        STX.W $4305
        LDA.B #$01
        STA.W $420B
