        RTS
        db $8B,$08,$0B,$4B,$AB,$C2,$30,$A5,$2C,$8D,$02,$00,$A9,$00,$00,$5B
        db $A8,$C2,$20,$B1,$00,$C9,$FF,$FF,$F0,$36,$E2,$20,$8D,$15,$21,$C8
        db $C2,$20,$B1,$00,$8D,$02,$43,$C8,$C8,$E2,$20,$B1,$00,$8D,$04,$43
        db $C8,$C2,$20,$B1,$00,$8D,$05,$43,$C8,$C8,$B1,$00,$18,$6D,$02,$00
        db $8D,$16,$21,$C8,$C8,$E2,$20,$A9,$01,$00,$8D,$0B,$42,$4C,$DA,$9F
        db $2B,$28,$AB,$6B
; [HUD] Updates heads-up display elements.
UpdateHUD:
        PHB
        PHP
        REP #$30
        LDA.W $1248
        BEQ ProcessSecondaryObjects
        JSR.W UpdateObjectData
        LDX.W #$0000
; [Collision] Sets up object collision parameters: loads from $10B8-$10C4 arrays indexed by X, calculates adjusted positions. Entry: 16-bit A/X/Y.
SetupObjectCollisionParameters:
        LDA.W $10B8,X
        STA.W $0000
        LDA.W $10BA,X
        STA.W $0002
        LDA.W $10C0,X
        STA.W $0008
        LDA.W $10C4,X
        STA.W $000C
        LDA.W $10C2,X
        TCD
        LDA.B $02
        SEC
        SBC.W $0521
        STA.W $0004
        LDA.W $10BE,X
        SEC
        SBC.W $0524
        CLC
        ADC.B $08
        STA.W $0006
        TDC
        CMP.W #$1670
        BCC HandleObjectCollisionCheck
        SEP #$20
        LDA.B $0B
        BNE ProcessObjectLoopEntry2
        BRA ProcessObjectLoopEntry1
; [Collision] Handles object collision detection based on position
HandleObjectCollisionCheck:
        SEP #$20
        LDA.B $2A
        BNE ProcessObjectLoopEntry2
; [Entity] Entry point 1 for object processing loop
ProcessObjectLoopEntry1:
        JSL.L ProcessSpriteData
        BRA ProcessAudioCommand
; [Entity] Entry point 2 for object processing loop
ProcessObjectLoopEntry2:
        JSL.L ProcessSpriteDataAlt
; [Music] Processes audio command: checks $12C2 and dispatches to appropriate handler
ProcessAudioCommand:
        REP #$20
        TXA
        CLC
        ADC.W #$0010
        TAX
        CPX.W $1248
        BNE SetupObjectCollisionParameters
        STZ.W $1248
        LDA.W #$0000
        TCD
; [Entity] Processes secondary objects if $0E20 != 0
ProcessSecondaryObjects:
        LDA.W $0E20
        BEQ ReturnFromLongSubroutine2
        LDX.W #$0000
; [Entity] Processes data for secondary object at index X
ProcessSecondaryObjectData:
        LDA.W $0D20,X
        STA.W $0000
        LDA.W $0D22,X
        STA.W $0002
        LDA.W $0D24,X
        STA.W $0004
        LDA.W $0D26,X
        STA.W $0006
        LDA.W $0D28,X
        STA.W $0008
        LDA.W $0D2A,X
        STA.W $000A
        LDA.W $0D2C,X
        STA.W $000C
        JSL.L ProcessSpriteData
        TXA
        CLC
        ADC.W #$0010
        TAX
        CPX.W $0E20
        BNE ProcessSecondaryObjectData
        STZ.W $0E20
; [Helper] Returns from long subroutine (PLP/PLB/RTL)
ReturnFromLongSubroutine2:
        PLP
        PLB
        RTL
; [Memory] Copies object data block using MVN instruction (14 bytes from $0F28 to $10B8)
CopyObjectDataMVN:
        REP #$30
        LDX.W #$0F28
        LDY.W #$10B8
        LDA.W #$000D
        MVN $00,$00
        PLP
        RTS
; [Entity] Updates object data structures, calls CopyObjectDataMVN if $1248 == $10
UpdateObjectData:
        PHP
        REP #$30
        LDA.W $1248
        CMP.W #$0010
        BEQ CopyObjectDataMVN
        SEC
        SBC.W #$0010
        STA.W $0040
        LDX.W #$0000
        TXY
        STX.W $0020
        STX.W $0028
        STX.W $002A
        STX.W $002C
        LDX.W #$0010
        STX.W $0022
; [Math] Finds minimum value in array, compares $0F2E values
FindMinValue:
        LDX.W $0022
        LDA.W $0F2E,X
        STA.W $005C
        LDX.W $002A
        LDA.W $0F2E,X
        CMP.W $005C
        BCC UpdateMinIndex
        BRA AdvanceLoopIndex
; [Math] Updates $002A with new minimum index
UpdateMinIndex:
        LDX.W $0022
        STX.W $002A
; [Helper] Advances loop index by $10 and checks for completion
AdvanceLoopIndex:
        LDA.W $0022
        CLC
        ADC.W #$0010
        STA.W $0022
        TYA
        CLC
        ADC.W #$0010
        TAY
        CMP.W $0040
        BNE FindMinValue
        PHY
        LDX.W $002A
        LDY.W $0020
        LDA.W $0F28,X
        STA.W $10B8,Y
        LDA.W $0F2A,X
        STA.W $10BA,Y
        LDA.W $0F2E,X
        STA.W $10BE,Y
        LDA.W $0F30,X
        STA.W $10C0,Y
        LDA.W $0F32,X
        STA.W $10C2,Y
        LDA.W $0F34,X
        STA.W $10C4,Y
        LDX.W $0020
        LDY.W $002A
        LDA.W $0F28,X
        STA.W $0F28,Y
        LDA.W $0F2A,X
        STA.W $0F2A,Y
        LDA.W $0F2E,X
        STA.W $0F2E,Y
        LDA.W $0F30,X
        STA.W $0F30,Y
        LDA.W $0F32,X
        STA.W $0F32,Y
        LDA.W $0F34,X
        STA.W $0F34,Y
        LDA.W $0020
        CLC
        ADC.W #$0010
        STA.W $0020
        STA.W $002A
        CLC
        ADC.W #$0010
        STA.W $0022
        PLY
        LDA.W $0020
        CMP.W $0040
        BEQ TransferObjectData
        LDA.W $0020
        TAY
        JMP.W FindMinValue
; [Memory] Transfers object data between buffers
TransferObjectData:
        LDX.W $002A
        LDY.W $0020
        LDA.W $0F28,X
        STA.W $10B8,Y
        LDA.W $0F2A,X
        STA.W $10BA,Y
        LDA.W $0F2E,X
        STA.W $10BE,Y
        LDA.W $0F30,X
        STA.W $10C0,Y
        LDA.W $0F32,X
        STA.W $10C2,Y
        LDA.W $0F34,X
        STA.W $10C4,Y
        PLP
        RTS
; [VRAM] Clears a specific area of VRAM based on frame counter.
ClearVRAMArea:
        PHB
        PHP
        REP #$30
        LDA.W $0F26
        AND.W #$0003
        BNE ReturnFromLongInit
        LDA.W #$2020
        STA.L $7E2000
        LDA.W #$00FE
        LDX.W #$2000
        TXY
        INY
        MVN $7E,$7E
; [Helper] Return from long initialization routine (PLP/PLB/RTL)
ReturnFromLongInit:
        PLP
        PLB
        RTL
        db $C2,$30,$2B,$FA,$AB,$28,$6B
; [OAM] Processes sprite data with bank switching and bounds checking
ProcessSpriteData:
        PHP
        PHB
        REP #$30
        PHX
        PHD
        SEP #$20
        LDA.W $0002
        PHA
        PLB
        REP #$20
        LDA.W #$0000
        TAY
        TCD
        LDX.W $00C4
        CPX.W #$02FC
        BCS SpriteProcessingComplete
; [OAM] Reads sprite data entry and checks for terminator
ReadSpriteEntry:
        REP #$20
        LDA.B ($00),Y
        CMP.W #$FFFF
        BNE ContinueSpriteProcessing
; [OAM] Handles completion of sprite data processing
SpriteProcessingComplete:
        PLD
        PLX
        PLB
        PLP
        RTL
; [OAM] Continues processing sprite data entries
ContinueSpriteProcessing:
        AND.W #$00FF
        BIT.W #$0080
        BEQ CheckSpriteYBoundsAlt
        ORA.W #$FF00
; [OAM] Checks sprite Y position bounds (similar to $80A30C)
CheckSpriteYBoundsAlt:
        CLC
        ADC.B $06
        CMP.W #$00E8
        BCC StoreSpriteYPosition
; [OAM] Alternative sprite entry skip routine
SkipSpriteEntryAlt:
        INY
        INY
        INY
        INY
        INY
        BRA ReadSpriteEntry
; [OAM] Stores sprite Y position in OAM buffer
StoreSpriteYPosition:
        SEP #$20
        STA.W $0001,X
        REP #$20
        LDA.B ($00),Y
        XBA
        AND.W #$00FF
        BIT.W #$0080
        BEQ CalculateSpriteXPosition
        ORA.W #$FF00
; [OAM] Calculates sprite X position with offset
CalculateSpriteXPosition:
        CLC
        ADC.B $04
        STA.B $32
        BMI ProcessSpriteEntry
        CMP.W #$01E0
        BCC StoreSpriteXPosition
        BRA SkipSpriteEntryAlt
; [OAM] Processes a sprite entry: stores X position, tile/attribute data to sprite buffer.
ProcessSpriteEntry:
        CMP.W #$FFF0
        BCC SkipSpriteEntryAlt
        LDA.B $32
        ORA.W #$FF00
        STA.B $32
; [OAM] Stores sprite X position in sprite buffer
StoreSpriteXPosition:
        LDA.B $32
        XBA
        LSR A
        ROR.B $C6
        ASL A
        XBA
        SEP #$20
        STA.W $0000,X
        INY
        INY
        REP #$20
        LDA.B ($00),Y
        CLC
        ADC.W $0008
        ORA.W $000C
        STA.W $0002,X
        INY
        INY
        INX
        INX
        INX
        INX
        STX.W $00C4
        LDA.B ($00),Y
        LSR A
        ROR.B $C6
        BCC ContinueSpriteLoop
        LDX.B $C2
        LDA.B $C6
        STA.B $00,X
        INX
        INX
        STX.B $C2
        LDA.W #$8000
        STA.B $C6
; [OAM] Continues sprite processing loop
ContinueSpriteLoop:
        INY
        LDX.B $C4
        CPX.W #$02FC
        BCS CODE_40A2C7
        JMP.W ReadSpriteEntry
CODE_40A2C7:
        PLD
        PLX
        PLB
        PLP
        RTL
        db $C2,$30,$2B,$FA,$AB,$28,$6B
; [OAM] Alternative sprite data processing routine
ProcessSpriteDataAlt:
        PHP
        PHB
        REP #$30
        PHX
        PHD
        SEP #$20
        SEP #$20
        LDA.W $0002
        PHA
        PLB
        REP #$20
        LDA.W #$0000
        TCD
        TAY
        LDX.W $00C4
        CPX.W #$02FC
        BCS CleanupAndReturnLong
; [OAM] Alternative sprite entry reading routine
ReadSpriteEntryAlt:
        REP #$20
        LDA.B ($00),Y
        STA.B $34
        CMP.W #$FFFF
        BNE SignExtendByte
; [Helper] Cleanup and return from long subroutine: restores registers and returns with RTL
CleanupAndReturnLong:
        PLD
        PLX
        PLB
        PLP
        RTL
; [Math] Sign-extends 8-bit value in A to 16-bit (handles negative values)
SignExtendByte:
        AND.W #$00FF
        BIT.W #$0080
        BEQ CheckSpriteYPosition
        ORA.W #$FF00
; [OAM] Checks if sprite Y position + offset < $E8, skips sprite if out of bounds
CheckSpriteYPosition:
        CLC
        ADC.B $06
        CMP.W #$00E8
        BCC StoreSpriteY
; [OAM] Skips current sprite entry (advances Y by 5 bytes)
SkipSpriteEntry:
        INY
        INY
        INY
        INY
        INY
        BRA ReadSpriteEntryAlt
; [OAM] Stores sprite Y position to OAM buffer
StoreSpriteY:
        SEP #$20
        STA.B $01,X
        PHY
        INY
        INY
        INY
        INY
        LDA.B ($00),Y
        BNE SetSpriteHeightF0
        LDA.B #$F8
        BRA CalculateSpriteX
; [OAM] Sets sprite height to $F0 (large sprite)
SetSpriteHeightF0:
        LDA.B #$F0
; [OAM] Calculates sprite X position with sign extension
CalculateSpriteX:
        SEC
        SBC.B $35
        REP #$20
        AND.W #$00FF
        BIT.W #$0080
        BEQ CheckSpriteXBounds
        ORA.W #$FF00
; [OAM] Checks if sprite X position is within screen bounds ($FFF0-$01E0)
CheckSpriteXBounds:
        CLC
        ADC.B $04
        STA.B $32
        BMI HandleNegativeX
        CMP.W #$01E0
        BCC StoreSpriteXAndTile
; [OAM] Skips sprite and restores Y register from stack
SkipSpriteAndRestoreY:
        PLY
        BRA SkipSpriteEntry
; [OAM] Handles negative X position (sign extends if >= $FFF0)
HandleNegativeX:
        CMP.W #$FFF0
        BCC SkipSpriteAndRestoreY
        LDA.B $32
        ORA.W #$FF00
        STA.B $32
; [OAM] Stores sprite X position and tile data to OAM buffer
