        ROR.B $C6
        ASL A
        XBA
        SEP #$20
        STA.B $00,X
        PLY
        INY
        INY
        REP #$20
        LDA.B ($00),Y
        CLC
        ADC.B $08
        ORA.B $0C
        EOR.W #$4000
        STA.B $02,X
        INY
        INY
        INX
        INX
        INX
        INX
        STX.W $00C4
        LDA.B ($00),Y
        INY
        LSR A
        ROR.B $C6
        BCC CheckSpriteBufferFull
        LDX.B $C2
        LDA.B $C6
        STA.B $00,X
        INX
        INX
        STX.B $C2
        LDA.W #$8000
        STA.B $C6
; [OAM] Checks if sprite buffer is full (X >= $02FC), jumps to cleanup if full
CheckSpriteBufferFull:
