        BCS SpriteBufferCleanup
; [OAM] Fills sprite buffer with termination values ($E000)
FillSpriteBuffer:
        LDA.W #$E000
        STA.B $00,X
        INX
        INX
        INX
        INX
        SEC
        ROR.B $C6
        LSR.B $C6
