        BCS SpriteBufferCleanup
        INY
        INY
        LDA.W #$E000
        STA.B $00,X
        STA.B $04,X
        STA.B $08,X
        STA.B $0C,X
        STA.B $10,X
        STA.B $14,X
        STA.B $18,X
        STA.B $1C,X
        LDA.W #$5555
        STA.W $0000,Y
        TXA
