; [Memory] Main data decompression routine. Uses bitstream processing with run-length encoding. Input: [$B4],Y = compressed data, $00BC = remaining bytes, $00B8 = output pointer. Output: decompressed data at [$B8].
DecompressData:
        PHB
        PHP
        PHK
        PLB
        REP #$30
        PHX
        PHY
        LDA.W #$0000
        STA.L $7EEFFF
        LDA.W #$0FED
        LDX.W #$EFFF
        TXY
        INY
        MVN $7E,$7E
        LDA.W #$0FEE
        STA.W $00B0
        STZ.W $00B2
        SEP #$20
        REP #$20
        LDY.W #$0000
; [Memory] Decompresses data stream with bitwise processing
DecompressDataStream:
        LSR.W $00B2
        LDA.W $00B2
        AND.W #$0100
        BNE ProcessCompressedBit
        LDA.B [$B4],Y
        INY
        DEC.W $00BC
        ORA.W #$FF00
        STA.W $00B2
; [Memory] Processes compressed data bit stream
ProcessCompressedBit:
        LDA.W $00B2
        AND.W #$0001
        BEQ HandleLiteralByte
        LDA.B [$B4],Y
        STA.B [$B8]
        INY
        INC.W $00B8
        DEC.W $00BC
        LDX.W $00B0
        STA.W $EFFF,X
        INX
        TXA
        AND.W #$0FFF
        STA.W $00B0
        BRA ContinueDecompression
; [Memory] Handles literal byte in decompression stream
HandleLiteralByte:
        LDA.B [$B4],Y
        AND.W #$00FF
        STA.W $00AA
        INY
        DEC.W $00BC
        LDA.B [$B4],Y
        STA.W $00AC
        INY
        DEC.W $00BC
        AND.W #$00F0
        ASL A
        ASL A
        ASL A
        ASL A
        ORA.W $00AA
        STA.W $00AA
        LDA.W $00AC
        AND.W #$000F
        INC A
        INC A
        INC A
        STA.W $00AC
        STZ.W $00AE
; [Memory] Processes compressed run-length data
ProcessCompressedRun:
        LDA.W $00AE
        INC.W $00AE
        CLC
        ADC.W $00AA
        AND.W #$0FFF
        TAX
        LDA.W $EFFF,X
        STA.B [$B8]
        INC.W $00B8
        LDX.W $00B0
        STA.W $EFFF,X
        INX
        TXA
        AND.W #$0FFF
        STA.W $00B0
        DEC.W $00AC
        BNE ProcessCompressedRun
; [Memory] Continues decompression loop
ContinueDecompression:
        LDA.W $00BC
        BMI DecompressionComplete
        JMP.W DecompressDataStream
; [Memory] Handles completion of decompression routine
DecompressionComplete:
        PLY
        PLX
        PLP
        PLB
        RTL
