; [Effects] Updates screen fade effect for intro/title screen transitions
FadeScreenUpdate:
        SEP #$30
        DEC.B $7B
        BNE FadeScreenLoop
        LDA.B $79
        BNE FadeScreenOut
        LDA.B #$04
        STA.B $7B
        REP #$20
        LDX.B $7A
        LDA.W $B160,X
        BNE FadeScreenHandler
        SEP #$20
        LDA.B #$1E
        STA.B $7B
        LDA.B #$01
        STA.B $79
        LDA.B #$00
        STA.B $78
        JMP.W FadeScreenLoop
; [Effects] Main fade screen handler - manages brightness updates and fade effects
FadeScreenHandler:
        STA.B $00
        JSR.W UploadVRAMDuringFade
        LDX.B $7A
        INX
        INX
        STX.B $7A
; [Effects] Main fade screen loop - calls brightness update and returns to fade handler.
FadeScreenLoop:
        JSR.W UpdateFadeTimer
        JMP.W FadeScreenUpdate
; [Effects] Updates screen brightness during fade effect.
UpdateFadeBrightness:
        JSR.W UpdateFadeTimer
        SEP #$20
        DEC.B $78
        BPL ApplyFadeBrightness
        JMP.W FadeScreenLoop
; [Effects] Applies fade brightness to COLDATA register ($2132) and continues fade loop.
ApplyFadeBrightness:
        LDA.B $78
        ORA.B #$E0
        STA.W $2132
        JMP.W UpdateFadeBrightness
; [Effects] Fades screen out by adjusting COLDATA ($2132) brightness.
FadeScreenOut:
        SEP #$20
        LDA.B $78
        INC A
        CMP.B #$20
        BEQ FadeCompleteReturn
        STA.B $78
        ORA.B #$E0
        STA.W $2132
        LDA.B #$02
        STA.B $7B
        JMP.W FadeScreenLoop
; [Helper] Returns when fade effect is complete.
FadeCompleteReturn:
        RTS
        db $AD,$12,$42,$29,$01,$D0,$F9,$AD,$19,$42,$0D,$1B,$42,$29,$10,$60
; [VRAM] Uploads data to VRAM during screen fade transitions using DMA.
