; [Memory] Cleanup and return from decompression routine. Restores processor status and data bank, returns to caller.
DecompressCleanup:
        PLP
        PLB
        RTL
; [Music] Main audio processing routine (called from UpdateTimers). Handles sound effects and music playback
AudioProcessingRoutine:
        PHB
        PHP
        REP #$20
        LDA.W $1274
        BMI DecompressCleanup
        LDA.W $00BC
        BPL DecompressDataBlock
; [Memory] Processes decompression data stream with bitwise handling and literal/compressed byte processing.
ProcessDecompressionStream:
        JSL.L ProcessDataStream
        LDA.W $1274
        BMI DecompressCleanup
; [Memory] Decompresses data block with bitstream processing and bank switching to WRAM.
DecompressDataBlock:
        SEP #$20
        LDA.B #$7E
        PHA
        PLB
        REP #$30
        LDY.W $1276
        LSR.W $00B2
        LDA.W $00B2
        AND.W #$0100
        BNE HandleCompressedByte
        LDA.B [$B4],Y
        INY
        STY.W $1276
        DEC.W $00BC
        BMI ProcessDecompressionStream
        ORA.W #$FF00
        STA.W $00B2
; [Memory] Handles compressed byte in decompression stream (literal vs compressed sequence).
HandleCompressedByte:
        LDA.W $00B2
        AND.W #$0001
        BEQ ReadCompressedByte
        SEP #$20
        LDA.B [$B4],Y
        STA.B [$B8]
        REP #$20
        INY
        STY.W $1276
        INC.W $00B8
        DEC.W $00BC
        BMI ProcessDecompressionStream
        LDX.W $00B0
        STA.W $EFFF,X
        INX
        TXA
        AND.W #$0FFF
        STA.W $00B0
        BRA CheckDataStreamSign
; [Memory] Reads compressed byte from stream, processes nibble packing
ReadCompressedByte:
        LDA.B [$B4],Y
        AND.W #$00FF
        STA.W $00AA
        INY
        STY.W $1276
        DEC.W $00BC
        BMI ProcessDecompressionStream
        LDA.B [$B4],Y
        STA.W $00AC
        INY
        STY.W $1276
        DEC.W $00BC
        BMI CODE_40D605
        AND.W #$00F0
        ASL A
        ASL A
        ASL A
        ASL A
        ORA.W $00AA
        STA.W $00AA
        LDA.W $00AC
        AND.W #$000F
        INC A
        INC A
        INC A
        STA.W $00AC
        STZ.W $00AE
; [Memory] Processes compressed data block with length in $00AC. Copies data from history buffer at $EFFF+X to destination.
ProcessCompressedBlock:
        LDA.W $00AE
        INC.W $00AE
        CLC
        ADC.W $00AA
        AND.W #$0FFF
        TAX
        SEP #$20
        LDA.W $EFFF,X
        STA.B [$B8]
        REP #$20
        INC.W $00B8
        LDX.W $00B0
        STA.W $EFFF,X
        INX
        TXA
        AND.W #$0FFF
        STA.W $00B0
        DEC.W $00AC
        BNE ProcessCompressedBlock
; [Memory] Checks sign of data stream at $00BC, processes if negative. Branches to return if positive.
CheckDataStreamSign:
        REP #$20
        LDA.W $00BC
        BPL ReturnFromDataProcessing
        db $22,$79,$BF,$80
; [Helper] Clean return from data processing functions. Restores processor status and data bank.
ReturnFromDataProcessing:
        PLP
        PLB
        RTL
        db $08,$E2,$20,$8D,$98,$12,$28,$6B
; [Music] Handles APU communication state machine: processes $129F state, sends commands to $2140-$2142
HandleAPUCommunication:
        SEP #$20
        LDA.W $129F
        BEQ UpdateAPUCommunication
        db $C9,$01,$D0,$12,$A9,$02,$8D,$9F,$12,$A9,$B4,$8D,$A0,$12,$A9,$01
        db $8D,$42,$21,$4C,$6F,$D6,$A9,$02,$8D,$9F,$12,$CE,$A0,$12,$F0,$12
        db $AD,$A0,$12,$C9,$02,$D0,$2D,$A9,$01,$8D,$BB,$12,$9C,$40,$21,$4C
        db $6F,$D6,$AD,$98,$12,$C9,$FF,$D0,$06,$9C,$98,$12,$9C,$BB,$12
; [Music] Updates APU communication: clears $129F, sends $1298 to $2140 if not FF, sets $12BB=0 and $1298=FF after sending
UpdateAPUCommunication:
        STZ.W $129F
        LDA.W $1298
        CMP.B #$FF
        BEQ SimpleReturnRTS
        db $8D,$40,$21,$9C,$BB,$12,$A9,$FF,$8D,$98,$12
; [Helper] Simple return from subroutine (RTS).
SimpleReturnRTS:
        RTS
        db $F0,$F2,$3A,$F0,$13,$3A,$F0,$25,$3A,$F0,$30,$3A,$F0,$3E,$3A,$F0
        db $50,$3A,$F0,$60,$A9,$00,$80,$DC,$CE,$A0,$12,$D0,$E2,$A9,$02,$8D
        db $40,$21,$A9,$06,$8D,$98,$12,$A9,$3C,$8D,$A0,$12,$60,$CE,$98,$12
        db $A9,$01,$8D,$BB,$12,$A9,$3C,$8D,$A0,$12,$60,$EE,$98,$12,$EE,$98
        db $12,$A9,$3C,$8D,$A0,$12,$A9,$01,$8D,$BB,$12,$60,$CE,$A0,$12,$D0
        db $AE,$A9,$03,$8D,$40,$21,$A9,$06,$8D,$98,$12,$A9,$3C,$8D,$A0,$12
        db $60,$CE,$A0,$12,$D0,$99,$CE,$98,$12,$A9,$3C,$8D,$A0,$12,$A9,$01
        db $8D,$40,$21,$60,$CE,$A0,$12,$D0,$08,$9C,$BB,$12,$A9,$FF,$8D,$98
        db $12,$60
; [Helper] Sets up data processing environment with register saving and bank setup.
SetupDataProcessing:
        PHD
        PHP
        PHB
        REP #$30
        PHX
        PHY
        PHA
        LDA.W #$0000
        TCD
        PLA
        PHK
        PLB
        TAY
        LDA.W $12A2
        BNE ProcessDataValue
        db $20,$78,$D8
; [Memory] Processes data value with validation and branching based on value and state.
ProcessDataValue:
        TYA
        TAY
        AND.W #$00FF
        CMP.W #$0000
        BEQ ClearAPUCommunication
        TYA
        LDX.W $1284
        TAY
        TXA
        CMP.W #$0014
        BEQ RestoreRegistersReturn
        TYA
        TXY
        DEX
        DEX
        BMI StoreAudioBuffer
        PHA
        AND.W #$FF7F
        STA.W $12B8
; [Music] Finds available audio slot by checking $12A4 array against $12B8
FindAudioSlot:
        LDA.W $12A4,X
        AND.W #$FF7F
        CMP.W $12B8
        BEQ CleanupAudioStack
        DEX
        DEX
        BPL FindAudioSlot
        PLA
; [Music] Stores value in audio buffer at $12A4,X and updates buffer pointer
StoreAudioBuffer:
        TYX
        STA.W $12A4,X
        INX
        INX
        STX.W $1284
        BRA RestoreRegistersReturn
; [Music] Clears APU communication ports and resets audio state
ClearAPUCommunication:
        SEP #$20
        STZ.W $2141
        STZ.W $2143
        REP #$20
        LDX.W #$0012
; [Music] Clears audio buffer by zeroing $12A4-$12B6 range
ClearAudioBuffer:
        STZ.W $12A4,X
        DEX
        DEX
        BPL ClearAudioBuffer
        STZ.W $1284
        STZ.W $1286
        BRA RestoreRegistersReturn
; [Helper] Cleans up stack after audio processing error
CleanupAudioStack:
        PLA
; [Helper] Restores all registers and returns from audio function
RestoreRegistersReturn:
        REP #$30
        PLY
        PLX
        PLB
        PLP
        PLD
        RTL
; [Music] Updates audio system state, handles APU communication.
UpdateAudioSystem:
        PHD
        PHP
        PHB
        REP #$30
        PHA
        PHX
        PHY
        LDA.W #$0000
        TCD
        PHK
        PLB
        LDA.W $12A2
        BNE ProcessAPUCommand
        JSR.W InitAudioState
; [Music] Processes APU command: checks $12BB, clears APU ports if non-zero, resets audio state, jumps to cleanup
ProcessAPUCommand:
        SEP #$20
        LDA.W $12BB
        BEQ ToggleAudioState
        db $9C,$41,$21,$9C,$43,$21,$C2,$20,$A2,$12,$00,$9E,$A4,$12,$CA,$CA
        db $10,$F9,$9C,$84,$12,$9C,$86,$12,$4C,$6C,$D8
; [Music] Toggles audio state $12A2 between 0 and 1, branches based on result
ToggleAudioState:
        REP #$20
        LDA.W $12A2
        INC A
        EOR.W #$FFFF
        INC A
        STA.W $12A2
        AND.W #$0001
        BEQ SendToAPUPorts
        SEP #$20
        LDA.W $1286
        BMI SendAPUData
        REP #$20
        LDA.W $1286
        PHA
        SEP #$20
        LDA.B #$FE
        BMI WriteAudioPorts
        db $C2,$20,$68,$09,$80,$00,$48
; [Music] Writes audio data to APU ports $2141/$2143 from stack
WriteAudioPorts:
        REP #$20
        PLA
        SEP #$20
        STA.W $2141
        XBA
        STA.W $2143
        REP #$20
        LDA.W #$00FE
        STA.W $1286
        JMP.W CleanupAudioState
; [Music] Sends data to APU: compares with FE, sends to $2141/$2143, clears bit 7 of $1286 if not FE
SendAPUData:
        SEP #$20
        CMP.B #$FE
        BEQ StoreAudioValue
        db $8D,$41,$21,$EB,$8D,$43,$21,$C2,$20,$AD,$86,$12,$29,$7F,$FF,$8D
        db $86,$12,$4C,$07,$D8,$C2,$20,$A9,$FE,$00
; [Music] Stores value to $1286 and jumps to cleanup routine
StoreAudioValue:
        REP #$20
        STA.W $1286
        JMP.W CleanupAudioState
; [Music] Sends $1286 to APU ports $2141/$2143, then processes $1284 pointer
SendToAPUPorts:
        REP #$20
        LDA.W $1286
        SEP #$20
        STA.W $2141
        XBA
        STA.W $2143
        REP #$20
        LDX.W $1284
        DEX
        DEX
        BMI SetAudioDefault
        LDA.W #$007F
        STA.W $1286
; [Music] Finds minimum value in audio buffer $12A4-$12B6
FindMinAudioBufferValue:
        LDA.W $12A4,X
        BEQ ContinueAudioBufferScan
        AND.W #$007F
        CMP.W $1286
        BCS ContinueAudioBufferScan
        STA.W $1286
        TXY
; [Music] Continues scanning audio buffer for minimum value
ContinueAudioBufferScan:
        DEX
        DEX
        BPL FindMinAudioBufferValue
        LDA.W $1286
        CMP.W #$007F
        BEQ ResetAudioBufferPointer
        TYX
        LDA.W $12A4,X
        STZ.W $12A4,X
        STA.W $1286
        LDX.W $1284
        LDA.W $12A4,X
        BEQ CleanupAudioState
        DEX
        DEX
        STX.W $1284
        JMP.W CleanupAudioState
; [Music] Resets audio buffer pointer when no valid values found
ResetAudioBufferPointer:
        STZ.W $1284
; [Music] Sets default audio value $00FE to $1286
SetAudioDefault:
        LDA.W #$00FE
        STA.W $1286
; [Music] Cleans up audio state: calls $D614, restores all registers from stack
CleanupAudioState:
        JSR.W HandleAPUCommunication
        REP #$30
        PLY
        PLX
        PLA
        PLB
        PLP
        PLD
        RTS
; [Music] Initializes audio state variables and buffers.
InitAudioState:
        REP #$20
        PHA
        LDA.W #$0001
        STA.W $12A2
        LDX.W #$0012
; [Music] Clears audio buffers $12A4-$12B6 (12 bytes)
ClearAudioBuffers:
        STZ.W $12A4,X
        DEX
        DEX
        BPL ClearAudioBuffers
        STZ.W $1284
        LDA.W #$00FE
        STA.W $1286
        LDA.W #$0002
        STA.W $12BA
        STZ.W $129F
        SEP #$20
        LDA.B #$FF
        STA.W $1298
        STZ.W $12BB
        REP #$20
        PLA
        RTS
; [Music] Calculates audio volume based on distance between $128A and $0521
CalculateAudioVolume:
        PHB
        PHP
        PHD
        REP #$30
        LDA.W $128A
        SEC
        SBC.W $0521
        BEQ SetupDataProcessingFE
        BMI SetupDataProcessingFE
        CMP.W #$00FF
        BEQ SetupDataProcessing01
        BCS SetupDataProcessing01
        SEP #$20
        EOR.B #$FF
        CMP.B #$FF
        XBA
        LDA.W $1288
        BRA SetupDataProcessingCommon
; [Helper] Sets up data processing with $01 in high byte
SetupDataProcessing01:
        SEP #$20
        LDA.B #$01
        XBA
        LDA.W $1288
        BRA SetupDataProcessingCommon
; [Helper] Sets up data processing with $FE in high byte
SetupDataProcessingFE:
        SEP #$20
        LDA.B #$FE
        XBA
        LDA.W $1288
; [Helper] Common setup for data processing functions
SetupDataProcessingCommon:
        JSL.L SetupDataProcessing
        PLD
        PLP
        PLB
        RTL
; [Helper] Sets up data processing with $80 in high byte
SetupDataProcessing80:
        PHP
        SEP #$20
        REP #$10
        XBA
        LDA.B #$80
        XBA
        JSL.L SetupDataProcessing
        PLP
        RTL
        db $20,$6C,$D7,$6B
; [Music] Audio dispatcher: sets up direct page, looks up handler from table $DA1F based on $12C0, stores to $08
AudioDispatcher:
        PHB
        PHP
        PHK
        PLB
        PHD
        REP #$30
        LDA.W #$0000
        TCD
        SEP #$20
        LDA.B #$00
        XBA
        LDA.W $12C0
        ASL A
        TAX
        REP #$20
        LDA.W $DA1F,X
        STA.B $08
        STZ.B $0C
        STZ.B $10
        STZ.B $1C
        LDA.W #$007F
        STA.B $1E
        STA.B $12
        STA.B $1A
        LDY.B $0C
        SEP #$20
        LDA.W $05F4
        STA.W $12C3
        LDA.B ($08),Y
        STA.W $12C2
        INY
        LDA.B ($08),Y
        STA.B $20
        INY
        LDA.B ($08),Y
        STA.B $21
        INY
        LDA.B ($08),Y
        STA.B $22
        INY
        STY.B $0C
        REP #$20
; [Helper] Return point for audio handlers: restores registers and returns
AudioHandlerReturn:
        LDY.B $1C
        LDA.B [$20],Y
        BEQ SetupDMAChannel1
        CLC
        ADC.B $1C
        CLC
        ADC.W #$0004
        STA.B $1C
        BRA AudioHandlerReturn
; [DMA] Configures DMA channel 1 for WRAM transfer
SetupDMAChannel1:
        SEP #$20
        STZ.W $4310
        LDA.B #$80
        STA.W $4311
        LDX.B $20
        STX.W $4312
        LDA.B $22
        STA.W $4314
        LDX.B $1C
        STX.W $4315
        LDX.B $10
        STX.W $2181
        LDA.B #$7F
        STA.W $2183
        JSR.W WaitForVBlankStart
        LDA.B #$02
        STA.W $420B
        REP #$20
        LDA.B $10
        CLC
        ADC.B $1C
        STA.B $10
        STA.B $18
        INC.B $10
        INC.B $10
        LDY.B $0C
        LDA.B ($08),Y
        INY
        INY
        STY.B $0C
        STA.B [$10]
        INC.B $10
        INC.B $10
        STZ.B $0E
; [GameState] Handles special event: processes event type and calls appropriate handler
HandleSpecialEvent:
        REP #$20
        LDY.B $0C
        LDA.B ($08),Y
        CMP.W #$FFFF
        BEQ AudioCleanup
        STA.W $0020
        INY
        INY
        LDA.B ($08),Y
        STA.W $0022
        INY
        STY.B $0C
        LDY.W #$0000
        LDA.B [$20],Y
        STA.W $4315
        STA.W $0028
        CLC
        ADC.B $0E
        STA.B $0E
        LDX.B $10
        STX.W $2181
        LDA.W $0010
        CLC
        ADC.W $0028
        STA.W $0010
        SEP #$20
        LDA.B #$7F
        STA.W $2183
        LDX.W $0020
        INX
        INX
        STX.W $4312
        LDA.W $0022
        STA.W $4314
        JSR.W WaitForVBlankStart
        LDA.B #$02
        STA.W $420B
        BRA HandleSpecialEvent
; [Music] Audio cleanup routine: restores stack and returns from audio processing
AudioCleanup:
        REP #$20
        LDA.B $0E
        STA.B [$18]
        LDA.W #$0000
        STA.B [$10]
        INC.B $10
        INC.B $10
        LDA.W #$0200
        STA.B [$10]
        STZ.W $0010
        SEP #$20
        LDA.B #$7F
        STA.W $0012
        JSR.W SPC700Boot
        PLD
        PLP
        PLB
        RTL
