; [Helper] Waits for V-blank to start by polling $4210 NMI flag.
WaitForVBlankStart:
        PHP
        SEP #$20
; [Helper] Waits for V-blank to end by polling $4210 NMI flag.
WaitForVBlankEnd:
        LDA.W $4210
        BMI WaitForVBlankEnd
; [Helper] Waits for V-blank to be active (NMI flag set).
WaitForVBlankActive:
        LDA.W $4210
        BPL WaitForVBlankActive
        LDA.W $4210
        PLP
        RTS
        db $BD,$C5,$DD,$01,$BD,$C5,$DD,$01,$BD,$C5,$DD,$01,$BD,$C5,$DD,$01
        db $BD,$C5,$DD,$01,$BD,$C5,$DD,$01,$BD,$C5,$DD,$01,$BD,$C5,$DD,$01
        db $BD,$C5,$DD,$01
; [Music] Uploads sound data to SPC700. Disables interrupts, calls SPC700Boot twice with different data pointers, then re-enables interrupts.
UploadSoundData:
        PHP
        SEI
        SEP #$20
        REP #$10
        LDX.W #$75DC
        STX.W $0010
        LDA.B #$DD
        STA.W $0012
        JSR.W SPC700Boot
        LDX.W #$0028
; [Timer] Simple delay loop using DEX countdown.
DelayLoop:
        DEX
        BNE DelayLoop
        LDX.W #$0000
        STX.W $0010
        LDA.B #$DD
        STA.W $0012
        JSR.W SPC700Boot
; [Helper] Enables interrupts (CLI), restores processor status (PLP), and returns long (RTL).
EnableIntAndReturn:
        CLI
        PLP
        RTL
; [Music] SPC700 boot/upload routine - initializes sound CPU
SPC700Boot:
        PHP
; [Music] Waits for SPC700 ready signal ($BBAA in $2140). Sets $2143 to $FF and polls until SPC acknowledges.
WaitForSPCReady:
        SEP #$20
        LDA.B #$FF
        STA.W $2143
; [Music] Main SPC700 program upload routine. Waits for SPC ready ($2140=$BBAA), then uploads data blocks from [$10],Y
UploadSPCProgram:
        REP #$30
        LDY.W #$0000
        LDA.W #$BBAA
        CMP.W $2140
        BNE WaitForSPCReady
        SEP #$20
        LDA.B #$CC
        BRA UploadSPCBlock
; [Music] Uploads single byte to SPC700. Reads from [$10],Y, increments Y, prepares for upload sequence
UploadSPCByte:
        LDA.B [$10],Y
        INY
        XBA
        LDA.B #$00
        BRA ProcessSPCUpload
; [Music] Uploads 16-bit word to SPC700. Reads two bytes, combines them, waits for acknowledgment at $2140
UploadSPCWord:
        XBA
        LDA.B [$10],Y
        INY
        XBA
; [Music] Waits for SPC700 acknowledgment by polling $2140 until value matches accumulator
WaitForSPCAck:
        CMP.W $2140
        BNE WaitForSPCAck
        INC A
; [Music] Processes SPC700 data upload. Stores value to $2140, switches between 8/16-bit modes for proper timing
ProcessSPCUpload:
        REP #$20
        STA.W $2140
        SEP #$20
        DEX
        BNE UploadSPCWord
; [Music] Uploads data to SPC700: waits for ready, adjusts counter, uploads data blocks with size/destination
UploadSPCData:
        CMP.W $2140
        BNE UploadSPCData
; [Music] Adjusts upload counter for SPC700 by adding 3, loops if result is zero.
AdjustSPCUploadCounter:
        ADC.B #$03
        BEQ AdjustSPCUploadCounter
; [Music] Uploads block of data to SPC700. Reads block size and destination address, sets up transfer.
UploadSPCBlock:
        PHA
        REP #$20
        LDA.B [$10],Y
        INY
        INY
        TAX
        LDA.B [$10],Y
        INY
        INY
        STA.W $2142
        SEP #$20
        CPX.W #$0001
        LDA.B #$00
        ROL A
        STA.W $2141
        ADC.B #$7F
        PLA
        STA.W $2140
; [Music] Waits for SPC700 acknowledgment by polling $2140 until value matches accumulator.
WaitForSPCAckLoop:
