; [Input] Manual controller reading routine. Reads controller 1 and 2 data via $4016/$4017 ports using bit-banging method. Stores results in $D6-$D9 (controller states).
ReadControllerManual:
        PHP
        SEP #$30
        STZ.B $DE
; [Input] Waits for controller to be ready by polling $4212 bit 0 (auto-joypad busy flag).
WaitForControllerReady:
        LDA.W $4212
        AND.B #$01
        BNE WaitForControllerReady
        STZ.W $4016
        LDA.B #$01
        STA.W $4016
        LDX.B #$08
; [Input] Reads 8 bits from controller 1 and 2 via $4016/$4017, rotating into $D7 and $D9.
ReadControllerBitsLoop:
        LDA.W $4016
        LSR A
        LSR A
        ROL.B $D7
        LDA.W $4017
        LSR A
        LSR A
        ROL.B $D9
        DEX
        BNE ReadControllerBitsLoop
        STZ.W $4016
        LDX.B #$08
; [Input] Reads controller input: polls $4016/$4017, rotates bits into $D6/$D8, checks for all buttons pressed
ReadControllerInput:
        LDA.W $4016
        LSR A
        LSR A
        ROL.B $D6
        LDA.W $4017
        LSR A
        LSR A
        ROL.B $D8
        DEX
        BNE ReadControllerInput
        LDA.B $D7
        CMP.B #$FF
        BNE CheckController2Input
        db $A5,$D6,$C9,$FF,$F0,$04,$A9,$80,$85,$DE
; [Input] Checks controller 2 input: compares $D9/$D8 with $FF, sets $DE bits for multi-controller
CheckController2Input:
        LDA.B $D9
        CMP.B #$FF
        BNE ReturnFromInputCheck
