; [Animation] Updates animation frames for all animated objects.
UpdateAnimations:
        PHB
        PHP
        PHK
        PLB
        REP #$30
        LDA.W #$0000
        TCD
        SEP #$20
        LDA.W $1478
        BEQ FadeCompleteCheck
        LDA.W $1479
        BNE CalculateFadeColor
        JSR.W CheckFadeDelay
; [Effects] Calculates faded color value based on progress and color components
CalculateFadeColor:
        LDA.W $147B
        CMP.B #$FF
        BEQ StoreFadedColor
        JMP.W CleanupFadeEffect
; [Effects] Stores faded color to palette buffer
StoreFadedColor:
        REP #$20
