; [Effects] Checks if fade effect is complete and updates flags
FadeCompleteCheck:
        PLP
        PLB
        RTL
; [Effects] Cleans up after fade effect: resets counters and flags
CleanupFadeEffect:
        LDA.W $147C
        BNE SetupNextFade
        LDA.W $147B
        STA.W $147C
        INC.W $147D
; [Effects] Sets up parameters for next fade effect
SetupNextFade:
        LDA.W $147D
        LSR A
        BCC UpdateFadeTimers
