        STZ.B $08
        LDA.W #$3600
        STA.B $0C
        LDA.W $147E
        STA.B $00
        LDA.W #$0080
        STA.B $02
        LDA.W #$000C
        CLC
        ADC.W $1480
        STA.B $04
        LDA.W #$00B0
        CLC
        ADC.W $1482
        STA.B $06
        JSL.L ProcessSpriteData
; [Timer] Updates fade timers and progress counters
UpdateFadeTimers:
        DEC.W $147C
