; [Input] Auto-joypad read routine. Uses SNES auto-read feature ($4218-$421F) to read all 4 controllers. Stores results in $0560-$0568 and processes directional inputs.
ReadControllerAuto:
        PHP
        REP #$20
        LDA.W $0560
        STA.W $0578
        LDA.W $0562
        STA.W $057A
        LDA.W $0564
        STA.W $057C
        LDA.W $0566
        STA.W $057E
        LDA.W $0568
        STA.W $0580
        SEP #$30
        STZ.B $DE
; [Input] Waits for auto-joypad read to complete by polling $4212 bit 0 (auto-joypad busy flag).
WaitForAutoReadReady:
        LDA.W $4212
        AND.B #$01
        BNE WaitForAutoReadReady
        LDA.W $4219
        STA.W $0561
        LDA.W $4218
        STA.W $0560
        AND.B #$0F
        STA.B $E3
        LDA.W $4016
        LSR A
        ROL.B $E3
        LDA.W $421B
        STA.W $0563
        LDA.W $421A
        STA.W $0562
        AND.B #$0F
        STA.B $E2
        LDA.W $421F
        STA.W $0565
        LDA.W $421E
        STA.W $0564
        AND.B #$0F
        STA.B $E1
        LDA.W $4017
        LSR A
        ROL.B $E2
        LSR A
        ROL.B $E1
        STZ.W $4201
        LDY.B #$10
; [Input] Controller read loop for auto-joypad routine. Reads 16 bits from controller 3/4 using $4017 polling.
ControllerReadLoop:
        LDA.W $4017
        REP #$20
        LSR A
        ROL.W $0566
        LSR A
        ROL.W $0568
        SEP #$20
        DEY
        BNE ControllerReadLoop
        LDA.W $0566
        AND.B #$0F
        STA.B $E0
        LDA.W $0568
        AND.B #$0F
        STA.B $DF
        LDA.W $4017
        LSR A
        ROL.B $E0
        LSR A
        ROL.B $DF
        LDA.B #$80
        STA.W $4201
        REP #$20
        LDA.W $0560
        EOR.W $0578
        AND.W $0560
        STA.W $056C
        LDA.W $0562
        EOR.W $057A
        AND.W $0562
        STA.W $056E
        LDA.W $0564
        EOR.W $057C
        AND.W $0564
        STA.W $0570
        LDA.W $0566
        EOR.W $057E
        AND.W $0566
        STA.W $0572
        LDA.W $0568
        EOR.W $0580
        AND.W $0568
        STA.W $0574
        LDA.W $056C
        ORA.W $056E
        ORA.W $0570
        ORA.W $0572
        ORA.W $0574
        STA.W $058A
        LDA.W $0560
        ORA.W $0562
        ORA.W $0564
        ORA.W $0566
        ORA.W $0568
        STA.W $058C
        PLP
        RTS
