; [Palette] Extracts RGB components from 15-bit color: separates $0320 into red, green, blue components in $0010-$0014
ExtractRGBComponents:
        PHP
        PHB
        SEP #$20
        LDA.B #$01
        STA.W $1655
        LDA.B #$7E
        STA.B $0A
        REP #$30
        LDA.W $0320
        AND.W #$001F
        STA.W $0010
        LDA.W $0320
        LSR A
        LSR A
        LSR A
        LSR A
        LSR A
        STA.W $0014
        AND.W #$001F
        STA.W $0012
        LDA.W $0014
        LSR A
        LSR A
        LSR A
        LSR A
        LSR A
        AND.W #$003F
        STA.W $0014
        LDA.W $0010
        BEQ DecrementGreenComponent
        DEC.W $0010
; [Palette] Decrements green component if non-zero
DecrementGreenComponent:
        LDA.W $0012
        BEQ DecrementBlueComponent
        DEC.W $0012
; [Palette] Decrements blue component if non-zero
DecrementBlueComponent:
        LDA.W $0014
        BEQ RecombineRGBComponents
        DEC.W $0014
; [Palette] Recombines RGB components: shifts blue/green components left, combines with red
RecombineRGBComponents:
        LDA.W $0014
        ASL A
        ASL A
        ASL A
        ASL A
        ASL A
        ASL A
        ASL A
        ASL A
        ASL A
        ASL A
        STA.W $0014
        LDA.W $0012
        ASL A
        ASL A
        ASL A
        ASL A
        ASL A
        STA.W $0012
        LDA.W $0010
        ORA.W $0012
        ORA.W $0014
        STA.W $0320
        LDX.W #$E500
        CPX.W $1647
        BNE ClearMemoryRange
        LDX.W #$E6E0
; [Memory] Clears memory range with $FF: fills $7E0000+X to $7E00DF+X with $FF
ClearMemoryRange:
        PHX
        LDA.W #$00FF
        LDY.W #$00DF
; [Memory] Memory fill loop: stores A to $7E0000+X, increments X, decrements Y
FillMemoryLoop:
        STA.L $7E0000,X
        INX
        INX
        DEY
        BPL FillMemoryLoop
        PLX
        STX.W $1647
        LDA.W $1645
        BEQ CleanupMemoryOp
        STA.B $06
        STA.B $04
        STZ.B $02
; [Math] Compares memory values $04 and $02, branches if $04 >= $02
CompareMemoryValues:
        LDA.B $04
        CMP.B $02
        BCS ProcessMemoryBlock
; [Helper] Cleans up memory operation: clears $1655, restores registers, returns
CleanupMemoryOp:
        SEP #$20
        STZ.W $1655
        PLB
        PLP
        RTL
; [Memory] Processes memory block: loads Y from $1647, processes data
ProcessMemoryBlock:
        LDY.W $1647
        LDA.W #$0000
        SEC
        SBC.B $04
        STA.B $0C
        LDA.W #$0000
        SEC
        SBC.B $02
        STA.B $0E
        JSR.W CalculateScreenPosition
        LDA.B $0E
        PHA
        LDA.B $0C
        STA.B $0E
        PLA
        STA.B $0C
        JSR.W CalculateScreenPosition
        LDA.B $02
        STA.B $0C
        JSR.W CalculateScreenPosition
        LDA.B $04
        STA.B $0C
        LDA.W #$0000
        SEC
        SBC.B $02
        STA.B $0E
        JSR.W CalculateScreenPosition
        INY
        LDA.W #$0000
        SEC
        SBC.B $04
        STA.B $0C
        LDA.B $02
        STA.B $0E
        JSR.W CalculateScreenPosition
        LDA.W #$0000
        SEC
        SBC.B $02
        STA.B $0C
        LDA.B $04
        STA.B $0E
        JSR.W CalculateScreenPosition
        LDA.B $02
        STA.B $0C
        JSR.W CalculateScreenPosition
        LDA.B $04
        STA.B $0C
        LDA.B $02
        STA.B $0E
        JSR.W CalculateScreenPosition
        LDA.B $02
        INC.B $02
        ASL A
        DEC A
        STA.B $00
        LDA.B $06
        SEC
        SBC.B $00
        STA.B $06
        BPL JumpToCompare
        DEC.B $04
        LDA.B $04
        ASL A
        CLC
        ADC.B $06
        STA.B $06
; [Helper] Jumps to comparison routine at $F49A
JumpToCompare:
        JMP.W CompareMemoryValues
; [Math] Calculates screen position: adds $0C to $1643, clamps to screen bounds (0-223)
CalculateScreenPosition:
        LDA.W $1643
        CLC
        ADC.B $0C
        BMI ReturnFromPositionCalc
        CMP.W #$00E0
        BCS ReturnFromPositionCalc
        ASL A
        STA.B $08
        LDA.W $1641
        CLC
        ADC.B $0E
        BPL ClampXPosition
        LDA.W #$0000
        BRA StoreToScreenBuffer
; [Math] Clamps X position to screen bounds (0-255)
ClampXPosition:
        CMP.W #$0100
        BCC StoreToScreenBuffer
        LDA.W #$00FF
; [Memory] Stores value to screen buffer at [$08],Y with 8-bit store
StoreToScreenBuffer:
        SEP #$20
        STA.B [$08],Y
        REP #$20
; [Helper] Returns from screen position calculation
ReturnFromPositionCalc:
        RTS
; [Helper] Looks up graphics value from table at $80F580 based on 8-bit index
LookupGraphicsValue:
        PHP
        REP #$30
        PHX
        AND.W #$00FF
        ASL A
        TAX
        LDA.L $80F580,X
        PLX
        PLP
        RTL
; Draws pixel to graphics buffer with color and position
DrawPixelToBuffer:
        PHP
        REP #$30
        PHX
        CLC
        ADC.W #$00C0
        AND.W #$00FF
        ASL A
        TAX
        LDA.L $80F580,X
        PLX
        PLP
